+import AdbDialog from '@smart/components-adb/molecules/AdbDialog/AdbDialog';
+
+import { CarType, OutletDetail } from '@smart/adb-shared';
+import { Text, TextArea } from '@smart/react-components';
+import { useAgentContext } from 'contexts/agent-context';
+import { useNotificationContext } from 'contexts/notification-context';
+import { ShowroomVehiclesDocument } from 'graphql/queries/cars.generated';
+import { useCurrentOutlet } from 'hooks/outlet';
+import { useState } from 'react';
+import { useTranslation } from 'react-i18next';
+import { useModal } from '../../Modal';
+import { useRemoveCarMutation } from '../CarActivation/queries.generated';
+
+const ConfirmModel = ({
+  vin,
+  outletDetail,
+}: {
+  vin: string;
+  outletDetail?: OutletDetail;
+}) => {
+  const { addNotification } = useNotificationContext();
+  const { closeModal } = useModal();
+  const outlet = useCurrentOutlet();
+  const { t } = useTranslation();
+  const [reason, setReason] = useState<string>('');
+  const { agent } = useAgentContext();
+
+  const [removeCar, { loading: removeCarLoading }] = useRemoveCarMutation({
+    onCompleted: (data) => {
+      if (data.removeCar.success) {
+        addNotification({
+          label: t('outlet.showroom.demo_cars.dialog.success'),
+          type: 'success',
+          message: t('outlet.showroom.demo_cars.dialog.success_describe'),
+        });
+        closeModal();
+      } else {
+        addNotification({
+          label: t('customer.register.error'),
+          type: 'error',
+          message: data.removeCar.message,
+        });
+      }
+    },
+    refetchQueries: [
+      {
+        query: ShowroomVehiclesDocument,
+        variables: {
+          input: {
+            outletId: outlet?.mcsId || '',
+            userId: agent?.email,
+          },
+        },
+      },
+    ],
+    awaitRefetchQueries: true,
+  });
+  if (outletDetail) {
+    return (
+      <AdbDialog
+        id="deactivate-car-dialog"
+        buttons={{
+          primary: {
+            label: t('outlet.showroom.demo_cars.dialog.confirm'),
+            onClick: () => {
+              removeCar({
+                variables: {
+                  input: {
+                    vin,
+                    customerId: outletDetail.outletId,
+                    userId: agent.email,
+                    carType: CarType.RemoveShowroomVehicle,
+                  },
+                },
+              });
+            },
+            isLoading: removeCarLoading,
+          },
+          secondary: {
+            label: t('outlet.showroom.demo_cars.dialog.cancel'),
+            onClick: closeModal,
+          },
+        }}
+      >
+        <AdbDialog.Header>
+          <Text variant="hl-100">
+            {t(
+              'outlet.showroom.demo_cars.dialog.confirm_sold_to_customer_title'
+            )}
+          </Text>
+        </AdbDialog.Header>
+        <AdbDialog.Content>
+          {t(`outlet.showroom.relocate.confirm_outlet_main_describe`)}：
+          <div>
+            {outletDetail?.name}，{outletDetail?.outletId}，
+            {outletDetail?.address?.city}，{outletDetail?.address?.line1}
+          </div>
+        </AdbDialog.Content>
+      </AdbDialog>
+    );
+  }
+  return (
+    <AdbDialog
+      id="deactivate-car-dialog"
+      buttons={{
+        primary: {
+          label: t('outlet.showroom.demo_cars.dialog.confirm'),
+          onClick: () => {
+            if (!reason) {
+              addNotification({
+                label: '',
+                type: 'error',
+                message: t(`outlet.showroom.relocate.reason`),
+              });
+            } else {
+              removeCar({
+                variables: {
+                  input: {
+                    vin,
+                    carType: CarType.RemoveShowroomVehicle,
+                    userId: agent.email,
+                    reason,
+                  },
+                },
+              });
+            }
+          },
+          isLoading: removeCarLoading,
+        },
+        secondary: {
+          label: t('outlet.showroom.demo_cars.dialog.cancel'),
+          onClick: closeModal,
+        },
+      }}
+    >
+      <AdbDialog.Header>
+        <Text variant="hl-100">
+          {t('outlet.showroom.demo_cars.dialog.other_reasons_title')}
+        </Text>
+      </AdbDialog.Header>
+      <AdbDialog.Content>
+        {t('outlet.showroom.demo_cars.dialog.other_reasons_content')}
+        <TextArea
+          label={t(`outlet.showroom.relocate.reason`)}
+          defaultValue={reason}
+          onChange={(e) => setReason(e.target.value)}
+        />
+      </AdbDialog.Content>
+    </AdbDialog>
+  );
+};
+
+export { ConfirmModel };

