@@ -0,0 +1,93 @@
+import { OutletDetail } from '@smart/adb-shared';
+import { Icon, Text } from '@smart/react-components';
+import { useState } from 'react';
+import { useTranslation } from 'react-i18next';
+import './DropdownList.scss';
+
+interface DropdownListProps {
+  outlets: OutletDetail[];
+  onSelect: (outlet: OutletDetail) => void;
+}
+
+const BASE_CLASS = 'dropdown-list';
+
+const DropdownList = ({ outlets, onSelect }: DropdownListProps) => {
+  const [selectOutlet, setSelectOutlet] = useState<string>('');
+
+  const { t } = useTranslation();
+
+  const handleSelect = (selectedOutlet: OutletDetail) => {
+    setSelectOutlet(selectedOutlet?.bpId ?? '');
+    onSelect(selectedOutlet);
+  };
+
+  return (
+    <div className={`${BASE_CLASS}`} role="listbox" aria-label="Select outlet">
+      {outlets.length === 0 ? (
+        <div className={`${BASE_CLASS}__empty`}>
+          <Text
+            variant="p-100"
+            color="c-high-contrast"
+            className={`${BASE_CLASS}__message`}
+            as="div"
+          >
+            {t('general.error_messages.empty_search_outlet')}
+          </Text>
+          <Text
+            variant="p-100"
+            color="c-high-contrast"
+            className={`${BASE_CLASS}__message`}
+            as="div"
+          >
+            {t('general.error_messages.empty_search_outlet_info')}
+          </Text>
+        </div>
+      ) : (
+        <ul className={`${BASE_CLASS}__list`}>
+          {outlets.map((outlet, index) => (
+            <div
+              key={outlet.outletId}
+              onClick={() => handleSelect(outlet)}
+              onKeyDown={(e) => {
+                if (e.key === 'Enter') {
+                  handleSelect(outlet);
+                }
+              }}
+              className={`${BASE_CLASS}__item`}
+              role="option"
+              tabIndex={index}
+              aria-selected={selectOutlet === outlet.bpId}
+              aria-label={`Select ${outlet.name} at ${outlet.address}`}
+            >
+              {selectOutlet === outlet.bpId && (
+                <Icon
+                  className={`${BASE_CLASS}__check`}
