@@ -0,0 +1,78 @@
+import { OutletDetail } from '@smart/adb-shared';
+import { Button, IconButton, TextInput } from '@smart/react-components';
+import { useOutletsContext } from 'contexts/outlets-context';
+import { useCurrentOutlet } from 'hooks/outlet';
+import { useState } from 'react';
+import { useTranslation } from 'react-i18next';
+import DropdownList from '../DropdownList/DropdownList';
+import './OutletDropdown.scss';
+
+const BASE_CLASS = 'outlet_dropdown';
+
+const OutletDropdown = ({
+  onSelect,
+}: {
+  onSelect: (outlet: OutletDetail) => void;
+}) => {
+  const { outlets } = useOutletsContext();
+  const { t } = useTranslation();
+  const currentOutlet = useCurrentOutlet();
+  const optionalOutlets = outlets.filter(
+    (item) => item.outletId !== currentOutlet?.mcsId
+  );
+  const [searchValue, setSearchValue] = useState('');
+  const [outletList, setOutletList] = useState<OutletDetail[]>(optionalOutlets);
+
+  const handleSearch = (value: string) => {
+    setSearchValue(value);
+
+    if (!value) {
+      setOutletList(optionalOutlets);
+      return;
+    }
+
+    const searchLower = value.toLowerCase();
+    const filteredOutlets = outlets.filter(
+      (outlet) =>
+        outlet.outletId?.toLowerCase().includes(searchLower) ||
+        outlet.name?.toLowerCase().includes(searchLower) ||
+        outlet.address?.city?.toLowerCase().includes(searchLower) ||
+        outlet.address?.line1?.toLowerCase().includes(searchLower)
+    );
+
+    setOutletList(filteredOutlets);
+  };
+
+  const handleClearSearchContent = () => {
+    setSearchValue('');
+    setOutletList(optionalOutlets);
+  };
+
+  return (
+    <div className={`${BASE_CLASS}`}>
+      <TextInput
+        className={`${BASE_CLASS}__search`}
+        label={t('general.labels.search_for_outlet')}
+        id="search"
+        value={searchValue}
+        trailing={
+          <IconButton
+            className={`${BASE_CLASS}__icon`}
+            variant="ghost"
+            onClick={handleClearSearchContent}
+          >
+            <Button.Icon
+              icon="close-without-circle"
+              aria-label="clear-search-content"
+            />
+          </IconButton>
+        }
+        onChange={(e) => handleSearch(e.target.value.trim())}
+      />
+
+      <DropdownList outlets={outletList} onSelect={onSelect} />
+    </div>
+  );
+};
+
+export default OutletDropdown;

