+import AdbDialog from '@smart/components-adb/molecules/AdbDialog/AdbDialog';
+
+import { Customer, CustomerAccountType, ShowroomCar } from '@smart/adb-shared';
+import { Text } from '@smart/react-components';
+import ShowroomVehicleSellingButton from 'pages/outlet/outlet-cars/VehicleOrderButton/VehicleOrderButton';
+import { useCallback, useEffect, useRef, useState } from 'react';
+import { useTranslation } from 'react-i18next';
+import { TypeAhead } from '../../TypeAhead/TypeAhead';
+import { TypeAheadPropList } from '../../TypeAhead/TypeAhead.config';
+
+const BASE_CLASS = 'adb-car-select-customer';
+const SelectCustomerModel = ({
+  customers,
+  car,
+}: {
+  car: ShowroomCar;
+  customers?: Customer[];
+}) => {
+  const { t } = useTranslation();
+  const [searchCustomerQuery, setSearchCustomerQuery] = useState<string>();
+  const [selectedCustomer, setSelectedCustomer] = useState<
+    Customer | undefined
+  >();
+  const [errorMessage, setErrorMessage] = useState<string>();
+  const formRef = useRef<HTMLButtonElement>(null);
+  const onChangeCustomerSearch = (value: string) => {
+    setSearchCustomerQuery(value);
+  };
+  const onSelectCustomer = useCallback(
+    (suggestion: TypeAheadPropList): void => {
+      if (customers) {
+        const selection = customers.find(
+          (customer) => customer.uuid === suggestion.id
+        );
+        setSelectedCustomer(selection);
+      }
+    },
+    [customers]
+  );
+
+  useEffect(() => {
+    if (customers && searchCustomerQuery) {
+      setErrorMessage(t('feature_calendar.general.no_result'));
+    } else {
+      setErrorMessage('');
+    }
+  }, [searchCustomerQuery, t, customers]);
+
+  return (
+    <AdbDialog
+      id="deactivate-car-dialog"
+      className={BASE_CLASS}
+      buttons={{
+        primary: {
+          label: t('outlet.showroom.demo_cars.dialog.confirm'),
+          onClick: () => {
+            formRef.current?.click();
+          },
+          isLoading: false,
+          disabled: !selectedCustomer,
+        },
+      }}
+    >
+      <AdbDialog.Header>
+        <Text variant="hl-50">
+          {t('customer.register.check_email_dialog.title')}
+        </Text>
+        <Text variant="cap-100">
+          （{t('customer.register.check_email_dialog.subtitle')}）
+        </Text>
+      </AdbDialog.Header>
+      <AdbDialog.Content>
+        <div className={`${BASE_CLASS}__content`}>
+          <TypeAhead
+            list={customers?.map((customer) => ({
+              id: customer.uuid ?? undefined,
+              title: `${customer?.firstName} ${customer?.lastName} - ${customer?.userId}`,
+            }))}
+            name="searchedCustomer"
+            delay={400}
+            onChange={onChangeCustomerSearch}
+            onSelect={onSelectCustomer}
+            label={t('feature_calendar.calendar_dialog.search')}
+            searchKey={searchCustomerQuery}
+            errorMessageMinLength={t('general.labels.enter_3_char')}
