+const ShowroomCarActivation = ({
+  car,
+  customers,
+}: {
+  car: ShowroomCar;
+  customers?: Customer[];
+}) => {
+  const { vin } = car;
+
+  const { t } = useTranslation();
+  const { registerModal } = useModal();
+
+  const removeAsset = () => {
+    registerModal(
+      <AdbDialog
+        id="relocate-car-dialog"
+        buttons={{
+          primary: {
+            label: t('outlet.showroom.relocate.buttons.relocate_to_outlet'),
+            onClick: () => {
+              registerModal(<RelocateModel vin={vin} />);
+            },
+            isLoading: false,
+          },
+          secondary: {
+            label: t('outlet.showroom.demo_cars.dialog.other_reasons'),
+            onClick: () => {
+              registerModal(<ConfirmModel vin={vin} />);
+            },
+          },
+        }}
+      >
+        <AdbDialog.Header>
+          <Text variant="hl-100">
+            {t('outlet.showroom.demo_cars.dialog.remove_title')}
+          </Text>
+        </AdbDialog.Header>
+        <AdbDialog.Content>
+          {t('outlet.showroom.demo_cars.dialog.remove_content')}
+        </AdbDialog.Content>
+      </AdbDialog>
+    );
+  };
+
+  return (
+    <div className={BASE_CLASS}>
+      {car.status === CarStatus.Active && (
+        <Flex justifyContent="end" gap={500}>
+          <Link asChild>
+            <Button onClick={removeAsset}>
+              {t('outlet.showroom.demo_cars.button.remove')}
+            </Button>
+          </Link>
+          <Button
+            variant="secondary"
+            onClick={() =>
+              registerModal(
+                <SelectCustomerModel customers={customers} car={car} />
+              )
+            }
+          >
+            {t('outlet.showroom.showroom_cars.button.sell_showroom_vehicle')}
+            <Button.Icon icon="arrow-right" />
+          </Button>
+        </Flex>
+      )}
+    </div>
+  );
+};
+
+export default ShowroomCarActivation;

