+            >
+              {outlet?.name}
+            </Text>
+
+            <div>
+              {showroomOrderingEnabled && (
+                <VehicleOrderButton type="showroom" variant="primary" />
+              )}
+            </div>
+          </div>
+          {!loading && filteredCars.length > 0 ? (
+            filteredCars.map((car) => (
+              <CarCard
+                key={car.vin}
+                car={car}
