+                type={AssetType.ShowroomVehicle}
+              >
+                <SimActivation vin={car.vin} />
+                {car.status === CarStatus.TransferOnHold && (
+                  <SimStatusContainer
+                    icon="error"
+                    iconBackground={IconBackground.WARNING}
+                    title={t(
+                      'outlet.showroom.showroom_cars.relocation_transferOnHold_description'
+                    )}
+                  />
+                )}
+                {car.status === CarStatus.Transferring && (
+                  <SimStatusContainer
+                    icon="error"
+                    iconBackground={IconBackground.WARNING}
+                    title={t(
+                      'outlet.showroom.showroom_cars.relocation_transferring_description'
+                    )}
+                  />
+                )}
+              </CarCard>
+            ))
+          ) : (
+            <LoadingIndicator loading={loading} onFullPage>
+              <EmptyLayout
+                message={t('general.error_messages.no_records_found')}
+              />
+            </LoadingIndicator>
+          )}
+        </div>
+      </AdbLayout.Content>
+    </div>
+  );
+};
+
+export default ShowroomVehicles;

