@@ -0,0 +1,77 @@
+import AdbDialog from '@smart/components-adb/molecules/AdbDialog/AdbDialog';
+
+import { CallCustomerAction, Task } from '@smart/adb-shared';
+import { useModal } from '@smart/components-adb/molecules/Modal';
+import { Text } from '@smart/react-components';
+import { Row } from '@tanstack/react-table';
+import { useAgentContext } from 'contexts/agent-context';
+import { useRelocationFeedbackMutation } from 'graphql/queries/tasks.generated';
+import { useTranslation } from 'react-i18next';
+
+const ConfirmModel = ({
+  onComplete,
+  relocationStatus,
+  task,
+}: {
+  relocationStatus: boolean;
+  onComplete: (refetchTaskAction: 'single' | 'all') => void;
+  task: Row<Task>;
+}) => {
+  const { closeModal } = useModal();
+  const { t } = useTranslation();
+  const { agent } = useAgentContext();
+
+  const [relocationFeedback, { loading: relocationFeedbackLoading }] =
+    useRelocationFeedbackMutation({
+      onCompleted: (data) => {
+        if (data.relocationFeedback.success) {
+          onComplete('all');
+          closeModal();
+        }
+      },
+    });
+
+  return (
+    <AdbDialog
+      id="relocation-task-dialog"
+      buttons={{
+        primary: {
+          label: relocationStatus
+            ? t('outlet.showroom.relocate.buttons.confirm_relocation')
+            : t('outlet.showroom.relocate.buttons.decline_relocation'),
+          onClick: () => {
+            relocationFeedback({
+              variables: {
+                input: {
+                  taskId: task.original.id,
+                  action: CallCustomerAction.CloseRelocationTask,
+                  vin: task.original.vin,
+                  relocationStatus,
+                  userId: agent.email,
+                },
+              },
+            });
+          },
+          isLoading: relocationFeedbackLoading,
+        },
+        secondary: {
+          label: t('outlet.showroom.demo_cars.dialog.cancel'),
+          onClick: closeModal,
+        },
+      }}
+    >
+      <AdbDialog.Header>
+        <Text variant="hl-100">
+          {relocationStatus
+            ? t('outlet.showroom.relocate.buttons.confirm_relocation')
+            : t('outlet.showroom.relocate.buttons.decline_relocation')}
+        </Text>
+      </AdbDialog.Header>
+      <AdbDialog.Content>
+        {t('outlet.showroom.relocate.task.describe')}
+      </AdbDialog.Content>
+    </AdbDialog>
+  );
+};
+
+export { ConfirmModel };

